Contents of file frontend/src/styles.css:

1 | @import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
2 | 
3 | :root {
4 |   font-family: 'Manrope', 'Segoe UI', sans-serif;
5 |   color: #202720;
6 |   background: #f3f5f2;
7 |   font-synthesis: none;
8 |   text-rendering: optimizeLegibility;
9 |   -webkit-font-smoothing: antialiased;
10 |   --ink: #202720;
11 |   --muted: #737b73;
12 |   --line: #dce1d9;
13 |   --accent: #c5ef62;
14 |   --mono: 'DM Mono', Consolas, monospace;
15 | }
16 | 
17 | * { box-sizing: border-box; }
18 | 
19 | body {
20 |   min-width: 320px;
21 |   min-height: 100vh;
22 |   margin: 0;
23 |   background:
24 |     radial-gradient(ellipse at 88% 20%, rgba(197, 239, 98, 0.16), transparent 31rem),
25 |     linear-gradient(135deg, #f8f9f6, #eef1ed 75%);
26 | }
27 | 
28 | button, a { font: inherit; }
29 | 
30 | .workspace {
31 |   display: flex;
32 |   min-height: 100vh;
33 |   flex-direction: column;
34 |   padding: 0 clamp(24px, 7vw, 108px);
35 | }
36 | 
37 | .topbar, .footer {
38 |   display: flex;
39 |   align-items: center;
40 |   justify-content: space-between;
41 | }
42 | 
43 | .topbar {
44 |   min-height: 82px;
45 |   border-bottom: 1px solid var(--line);
46 | }
47 | 
48 | .brand {
49 |   display: inline-flex;
50 |   align-items: center;
51 |   gap: 11px;
52 |   color: var(--ink);
53 |   font-size: 15px;
54 |   font-weight: 800;
55 |   text-decoration: none;
56 | }
57 | 
58 | .brand__mark {
59 |   display: grid;
60 |   width: 30px;
61 |   aspect-ratio: 1;
62 |   place-items: center;
63 |   border-radius: 8px;
64 |   background: var(--ink);
65 |   color: var(--accent);
66 |   font-family: var(--mono);
67 |   font-size: 15px;
68 | }
69 | 
70 | .topbar__label, .footer, .eyebrow, .overview__note {
71 |   font-family: var(--mono);
72 |   font-size: 11px;
73 |   letter-spacing: 0;
74 | }
75 | 
76 | .topbar__label, .footer { color: var(--muted); }
77 | 
78 | .overview {
79 |   width: min(100%, 920px);
80 |   margin: auto;
81 |   padding: 88px 0 104px;
82 |   animation: arrive 560ms ease-out both;
83 | }
84 | 
85 | .eyebrow {
86 |   margin: 0 0 24px;
87 |   color: #586358;
88 |   text-transform: uppercase;
89 | }
90 | 
91 | .eyebrow span { padding: 0 7px; color: #a6ada5; }
92 | 
93 | h1 {
94 |   margin: 0;
95 |   font-size: clamp(48px, 7vw, 82px);
96 |   font-weight: 600;
97 |   line-height: 1.04;
98 | }
99 | 
100 | .overview__note {
101 |   margin: 62px 0 14px;
102 |   color: var(--muted);
103 |   text-transform: uppercase;
104 | }
105 | 
106 | .api-status {
107 |   display: flex;
108 |   min-height: 102px;
109 |   align-items: center;
110 |   gap: 18px;
111 |   border-top: 1px solid var(--line);
112 |   border-bottom: 1px solid var(--line);
113 | }
114 | 
115 | .api-status__indicator {
116 |   width: 10px;
117 |   aspect-ratio: 1;
118 |   flex: none;
119 |   border-radius: 50%;
120 |   background: #a8afa7;
121 | }
122 | 
123 | .api-status--connected .api-status__indicator { background: #5f9d3b; }
124 | .api-status--unavailable .api-status__indicator { background: #c55b47; }
125 | 
126 | .api-status .eyebrow { margin: 0 0 5px; font-size: 10px; }
127 | .api-status h2 { margin: 0; font-size: 16px; font-weight: 700; }
128 | .api-status__detail { margin: 4px 0 0; color: var(--muted); font-family: var(--mono); font-size: 11px; }
129 | 
130 | .upload-section {
131 |   display: grid;
132 |   grid-template-columns: minmax(180px, 0.7fr) minmax(0, 1.3fr);
133 |   align-items: center;
134 |   gap: 24px;
135 |   padding: 28px 0;
136 |   border-bottom: 1px solid var(--line);
137 | }
138 | 
139 | .upload-section__heading .eyebrow { margin: 0 0 7px; font-size: 10px; }
140 | .upload-section__heading h2 { margin: 0; font-size: 17px; font-weight: 700; }
141 | 
142 | .project-upload__form {
143 |   display: flex;
144 |   min-width: 0;
145 |   align-items: center;
146 |   gap: 12px;
147 | }
148 | 
149 | .project-upload__picker {
150 |   display: grid;
151 |   min-width: 0;
152 |   flex: 1;
153 |   gap: 7px;
154 |   color: var(--muted);
155 |   font-family: var(--mono);
156 |   font-size: 10px;
157 |   text-transform: uppercase;
158 | }
159 | 
160 | .project-upload__picker input {
161 |   width: 100%;
162 |   min-width: 0;
163 |   color: var(--ink);
164 |   font-family: 'Manrope', 'Segoe UI', sans-serif;
165 |   font-size: 12px;
166 |   text-transform: none;
167 | }
168 | 
169 | .project-upload__picker input::file-selector-button {
170 |   min-height: 36px;
171 |   margin-right: 10px;
172 |   padding: 0 11px;
173 |   border: 1px solid var(--line);
174 |   border-radius: 5px;
175 |   background: #fff;
176 |   color: var(--ink);
177 |   cursor: pointer;
178 | }
179 | 
180 | .project-upload__form button {
181 |   min-height: 40px;
182 |   flex: none;
183 |   padding: 0 15px;
184 |   border: 0;
185 |   border-radius: 5px;
186 |   background: var(--ink);
187 |   color: #fff;
188 |   cursor: pointer;
189 |   font-size: 12px;
190 |   font-weight: 700;
191 | }
192 | 
193 | .project-upload__form button:disabled { cursor: not-allowed; opacity: 0.45; }
194 | .project-upload__hint, .project-upload__message { margin: 8px 0 0; color: var(--muted); font-size: 11px; }
195 | .project-upload__message { overflow-wrap: anywhere; line-height: 1.6; }
196 | .project-upload__message--error { color: #a43d2c; }
197 | .project-upload__message code { font-family: var(--mono); }
198 | 
199 | .footer {
200 |   min-height: 60px;
201 |   border-top: 1px solid var(--line);
202 | }
203 | 
204 | @keyframes arrive {
205 |   from { opacity: 0; transform: translateY(10px); }
206 |   to { opacity: 1; transform: translateY(0); }
207 | }
208 | 
209 | @media (max-width: 560px) {
210 |   .topbar { min-height: 68px; }
211 |   .topbar__label { font-size: 10px; }
212 |   .overview { padding: 74px 0 84px; }
213 |   h1 { font-size: 52px; }
214 |   .overview__note { margin-top: 48px; }
215 |   .upload-section { grid-template-columns: 1fr; gap: 18px; }
216 |   .project-upload__form { align-items: stretch; flex-direction: column; }
217 |   .project-upload__form button { width: 100%; }
218 | }
219 | 
220 | @media (prefers-reduced-motion: reduce) {
221 |   *, *::before, *::after { animation-duration: 0.01ms !important; }
222 | }
223 | 
224 | .dashboard-shell {
225 |   min-height: 100vh;
226 |   padding: 0 clamp(16px, 4vw, 56px);
227 | }
228 | 
229 | .dashboard-shell .topbar {
230 |   display: grid;
231 |   min-height: 72px;
232 |   grid-template-columns: minmax(150px, 1fr) minmax(0, 2fr) auto;
233 |   gap: 20px;
234 |   border-bottom: 1px solid var(--line);
235 | }
236 | 
237 | .topbar__project {
238 |   display: grid;
239 |   min-width: 0;
240 |   gap: 2px;
241 | }
242 | 
243 | .topbar__caption, .topbar__environment {
244 |   color: var(--muted);
245 |   font-family: var(--mono);
246 |   font-size: 10px;
247 |   text-transform: uppercase;
248 | }
249 | 
250 | .topbar__project-name {
251 |   overflow: hidden;
252 |   font-size: 13px;
253 |   font-weight: 700;
254 |   text-overflow: ellipsis;
255 |   white-space: nowrap;
256 | }
257 | 
258 | .topbar__environment {
259 |   padding: 6px 8px;
260 |   border: 1px solid var(--line);
