262 | }
263 | 
264 | .dashboard-grid {
265 |   display: grid;
266 |   width: min(100%, 1680px);
267 |   min-height: calc(100vh - 73px);
268 |   grid-template-columns: 260px minmax(0, 1fr);
269 |   margin: 0 auto;
