279 | 
280 | .sidebar__heading, .section-heading {
281 |   display: flex;
282 |   align-items: center;
283 |   justify-content: space-between;
284 | }
285 | 
286 | .sidebar__heading { padding: 0 8px 14px; }
287 | .sidebar__heading h2, .section-heading h2 { margin: 0; font-size: 13px; font-weight: 700; }
288 | .sidebar__heading > span, .section-heading > span { color: var(--muted); font-family: var(--mono); font-size: 10px; }
289 | .sidebar__tree { flex: 1; min-height: 90px; }
290 | .tree-state { margin: 12px 8px; color: var(--muted); font-size: 12px; }
291 | 
292 | .sidebar__status {
293 |   margin-top: 24px;
294 |   padding: 14px 8px 0;
295 |   border-top: 1px solid var(--line);
296 | }
297 | 
298 | .sidebar__status .api-status {
299 |   min-height: 0;
300 |   align-items: flex-start;
301 |   gap: 9px;
302 |   border: 0;
303 | }
304 | 
305 | .sidebar__status .api-status__indicator { margin-top: 5px; }
306 | .sidebar__status .api-status h2 { font-size: 12px; }
307 | .sidebar__status .api-status__detail { font-size: 10px; }
308 | 
309 | .content-area {
310 |   min-width: 0;
311 |   padding: 27px clamp(20px, 4vw, 52px) 48px;
312 | }
313 | 
