323 | 
324 | .content-toolbar .eyebrow { margin: 0 0 6px; font-size: 10px; }
325 | .content-toolbar h1 { margin: 0; font-size: 24px; font-weight: 700; line-height: 1.25; }
326 | .content-toolbar .project-upload { min-width: 310px; }
327 | .content-toolbar .project-upload__hint { display: none; }
328 | .content-toolbar .project-upload__message { max-width: 420px; }
329 | 
