335 | .error-banner {
336 |   margin: 18px 0 0;
337 |   padding: 10px 12px;
338 |   border-left: 3px solid #bc5843;
339 |   background: rgba(188, 88, 67, 0.08);
340 |   color: #8d3527;
341 |   font-size: 12px;
342 |   overflow-wrap: anywhere;
